insert into vocabulary (id, word, ipa, part_of_speech, translation_pt, example_en, example_pt, cefr_level, tags) values
('30000000-0000-0000-0000-000000002221', 'analysis', '/əˈnæləsɪs/', 'noun', 'análise', 'The analysis revealed several unexpected trends.', 'A análise revelou várias tendências inesperadas.', 'C1', array['nominalization']),
('30000000-0000-0000-0000-000000002222', 'evaluation', '/ɪˌvæljuˈeɪʃən/', 'noun', 'avaliação', 'The evaluation of the new system took several weeks.', 'A avaliação do novo sistema levou várias semanas.', 'C1', array['nominalization']),
('30000000-0000-0000-0000-000000002223', 'assessment', '/əˈsesmənt/', 'noun', 'avaliação, diagnóstico', 'The initial assessment identified three major risks.', 'O diagnóstico inicial identificou três riscos principais.', 'C1', array['nominalization']),
('30000000-0000-0000-0000-000000002224', 'investigation', '/ɪnˌvestɪˈɡeɪʃən/', 'noun', 'investigação', 'The investigation into the delay is still ongoing.', 'A investigação sobre o atraso ainda está em andamento.', 'C1', array['nominalization']),
('30000000-0000-0000-0000-000000002225', 'conclusion', '/kənˈkluːʒən/', 'noun', 'conclusão', 'The report reaches a clear conclusion about the causes.', 'O relatório chega a uma conclusão clara sobre as causas.', 'C1', array['nominalization']),
('30000000-0000-0000-0000-000000002226', 'description', '/dɪˈskrɪpʃən/', 'noun', 'descrição', 'The document includes a detailed description of the process.', 'O documento inclui uma descrição detalhada do processo.', 'C1', array['nominalization']),
('30000000-0000-0000-0000-000000002227', 'development', '/dɪˈveləpmənt/', 'noun', 'desenvolvimento', 'The development of the new product took over a year.', 'O desenvolvimento do novo produto levou mais de um ano.', 'C1', array['nominalization']),
('30000000-0000-0000-0000-000000002228', 'achievement', '/əˈtʃiːvmənt/', 'noun', 'realização, conquista', 'Reducing costs by twenty percent was a major achievement.', 'Reduzir os custos em vinte por cento foi uma grande conquista.', 'C1', array['nominalization']),
('30000000-0000-0000-0000-000000002229', 'performance', '/pərˈfɔːrməns/', 'noun', 'desempenho', 'The team''s performance improved significantly this quarter.', 'O desempenho da equipe melhorou significativamente neste trimestre.', 'C1', array['nominalization']),
('30000000-0000-0000-0000-000000002230', 'improvement', '/ɪmˈpruːvmənt/', 'noun', 'melhoria', 'There has been a steady improvement in customer satisfaction.', 'Houve uma melhoria constante na satisfação do cliente.', 'C1', array['nominalization']),
('30000000-0000-0000-0000-000000002231', 'involvement', '/ɪnˈvɒlvmənt/', 'noun', 'envolvimento', 'Her involvement in the project was crucial to its success.', 'O envolvimento dela no projeto foi crucial para o sucesso.', 'C1', array['nominalization']),
('30000000-0000-0000-0000-000000002232', 'requirement', '/rɪˈkwaɪərmənt/', 'noun', 'requisito', 'Meeting this requirement is essential for approval.', 'Cumprir esse requisito é essencial para a aprovação.', 'C1', array['nominalization']),
('30000000-0000-0000-0000-000000002233', 'significance', '/sɪɡˈnɪfɪkəns/', 'noun', 'importância, significância', 'The significance of these findings cannot be overstated.', 'A importância dessas descobertas não pode ser subestimada.', 'C1', array['nominalization']),
('30000000-0000-0000-0000-000000002234', 'effectiveness', '/ɪˈfektɪvnəs/', 'noun', 'eficácia', 'The effectiveness of the new policy is still being measured.', 'A eficácia da nova política ainda está sendo medida.', 'C1', array['nominalization']),
('30000000-0000-0000-0000-000000002235', 'accuracy', '/ˈækjərəsi/', 'noun', 'precisão', 'The accuracy of the forecast depends on reliable data.', 'A precisão da previsão depende de dados confiáveis.', 'C1', array['nominalization']),
('30000000-0000-0000-0000-000000002236', 'consistency', '/kənˈsɪstənsi/', 'noun', 'consistência', 'Consistency in the data collection process is essential.', 'A consistência no processo de coleta de dados é essencial.', 'C1', array['nominalization']),
('30000000-0000-0000-0000-000000002237', 'validity', '/vəˈlɪdəti/', 'noun', 'validade', 'Researchers questioned the validity of the results.', 'Os pesquisadores questionaram a validade dos resultados.', 'C1', array['nominalization']),
('30000000-0000-0000-0000-000000002238', 'complexity', '/kəmˈpleksəti/', 'noun', 'complexidade', 'The complexity of the system makes it hard to maintain.', 'A complexidade do sistema dificulta a manutenção.', 'C1', array['nominalization']),
('30000000-0000-0000-0000-000000002239', 'reduction', '/rɪˈdʌkʃən/', 'noun', 'redução', 'The company achieved a significant reduction in expenses.', 'A empresa conseguiu uma redução significativa nas despesas.', 'C1', array['nominalization']),
('30000000-0000-0000-0000-000000002240', 'distribution', '/ˌdɪstrɪˈbjuːʃən/', 'noun', 'distribuição', 'The distribution of resources varies widely by region.', 'A distribuição de recursos varia muito por região.', 'C1', array['nominalization']),
('30000000-0000-0000-0000-000000002241', 'correlation', '/ˌkɒrəˈleɪʃən/', 'noun', 'correlação', 'There is a strong correlation between the two variables.', 'Há uma forte correlação entre as duas variáveis.', 'C1', array['nominalization']),
('30000000-0000-0000-0000-000000002242', 'emergence', '/ɪˈmɜːrdʒəns/', 'noun', 'surgimento', 'The emergence of new technologies changed the industry.', 'O surgimento de novas tecnologias mudou a indústria.', 'C1', array['nominalization']),
('30000000-0000-0000-0000-000000002243', 'occurrence', '/əˈkɜːrəns/', 'noun', 'ocorrência', 'Delays have become a common occurrence this year.', 'Os atrasos se tornaram uma ocorrência comum este ano.', 'C1', array['nominalization']),
('30000000-0000-0000-0000-000000002244', 'variation', '/ˌveriˈeɪʃən/', 'noun', 'variação', 'There is considerable variation in the results across regions.', 'Há uma variação considerável nos resultados entre regiões.', 'C1', array['nominalization']),
('30000000-0000-0000-0000-000000002245', 'implication', '/ˌɪmplɪˈkeɪʃən/', 'noun', 'implicação', 'The findings have important implications for future policy.', 'As descobertas têm implicações importantes para políticas futuras.', 'C1', array['nominalization']),
('30000000-0000-0000-0000-000000002246', 'assumption', '/əˈsʌmpʃən/', 'noun', 'suposição, premissa', 'The forecast is based on a reasonable assumption.', 'A previsão se baseia em uma premissa razoável.', 'C1', array['nominalization']),
('30000000-0000-0000-0000-000000002247', 'interpretation', '/ɪnˌtɜːrprɪˈteɪʃən/', 'noun', 'interpretação', 'Different readers may have a different interpretation of the data.', 'Leitores diferentes podem ter uma interpretação diferente dos dados.', 'C1', array['nominalization']),
('30000000-0000-0000-0000-000000002248', 'observation', '/ˌɒbzərˈveɪʃən/', 'noun', 'observação', 'Careful observation revealed a pattern the team had missed.', 'Uma observação cuidadosa revelou um padrão que a equipe havia perdido.', 'C1', array['nominalization']),
('30000000-0000-0000-0000-000000002249', 'contribution', '/ˌkɒntrɪˈbjuːʃən/', 'noun', 'contribuição', 'Her contribution to the project was widely recognized.', 'A contribuição dela para o projeto foi amplamente reconhecida.', 'C1', array['nominalization']),
('30000000-0000-0000-0000-000000002250', 'limitation', '/ˌlɪmɪˈteɪʃən/', 'noun', 'limitação', 'Every study has some limitation that should be acknowledged.', 'Todo estudo tem alguma limitação que deve ser reconhecida.', 'C1', array['nominalization']);

