-- Lição 371: Substantivos de investigação e análise (analysis, evaluation, assessment, investigation, conclusion, description)
insert into exercises (lesson_id, type, sort_order, content) values
('20000000-0000-0000-0000-000000000371', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000002221", "show_image": false}'),
('20000000-0000-0000-0000-000000000371', 'flashcard', 2, '{"vocabulary_id": "30000000-0000-0000-0000-000000002223", "show_image": false}'),
('20000000-0000-0000-0000-000000000371', 'flashcard', 3, '{"vocabulary_id": "30000000-0000-0000-0000-000000002225", "show_image": false}'),
('20000000-0000-0000-0000-000000000371', 'multiple_choice', 4, '{"question": "The ___ revealed several unexpected trends.", "audio_text": null, "options": ["analysis", "achievement", "requirement"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000371', 'multiple_choice', 5, '{"question": "The initial ___ identified three major risks.", "audio_text": null, "options": ["assessment", "description", "development"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000371', 'matching', 6, '{"pairs": [{"left": "analysis", "right": "análise"}, {"left": "evaluation", "right": "avaliação"}, {"left": "assessment", "right": "avaliação, diagnóstico"}, {"left": "investigation", "right": "investigação"}, {"left": "conclusion", "right": "conclusão"}, {"left": "description", "right": "descrição"}]}'),
('20000000-0000-0000-0000-000000000371', 'fill_blank', 7, '{"sentence": "The ___ into the delay is still ongoing.", "options": ["investigation", "achievement", "performance"], "correct": "investigation", "translation": "A investigação sobre o atraso ainda está em andamento."}'),
('20000000-0000-0000-0000-000000000371', 'fill_blank', 8, '{"sentence": "The document includes a detailed ___ of the process.", "options": ["description", "assumption", "correlation"], "correct": "description", "translation": "O documento inclui uma descrição detalhada do processo."}'),
('20000000-0000-0000-0000-000000000371', 'word_order', 9, '{"words": ["The", "evaluation", "of", "the", "new", "system", "took", "several", "weeks"], "correct_sentence": "The evaluation of the new system took several weeks", "translation": "A avaliação do novo sistema levou várias semanas"}'),
('20000000-0000-0000-0000-000000000371', 'word_order', 10, '{"words": ["The", "report", "reaches", "a", "clear", "conclusion", "about", "the", "causes"], "correct_sentence": "The report reaches a clear conclusion about the causes", "translation": "O relatório chega a uma conclusão clara sobre as causas"}'),
('20000000-0000-0000-0000-000000000371', 'reading', 11, '{"passage": "In academic and formal writing, verbs are often turned into nouns for a more objective, impersonal tone. Instead of ''we analyzed the data'', writers prefer ''the analysis revealed...''. Similarly, ''evaluate'' becomes ''evaluation'', ''assess'' becomes ''assessment'', ''investigate'' becomes ''investigation'', ''conclude'' becomes ''conclusion'', and ''describe'' becomes ''description''. This process is called nominalization.", "translation": "Na escrita acadêmica e formal, verbos costumam ser transformados em substantivos para um tom mais objetivo e impessoal. Em vez de ''we analyzed the data'', autores preferem ''the analysis revealed...''. Da mesma forma, ''evaluate'' vira ''evaluation'', ''assess'' vira ''assessment'', ''investigate'' vira ''investigation'', ''conclude'' vira ''conclusion'', e ''describe'' vira ''description''. Esse processo é chamado de nominalização.", "question": "What is the process of turning verbs into nouns called, according to the text?", "options": ["Nominalization", "Subordination", "Reduction"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000371', 'listening', 12, '{"audio_text": "The analysis revealed several unexpected trends. The initial assessment identified three major risks. The investigation into the delay is still ongoing.", "question": "What did the initial assessment identify, according to the audio?", "options": ["Three major risks", "Unexpected trends", "A delay"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000371', 'dictation', 13, '{"audio_text": "The analysis revealed several unexpected trends.", "expected": "The analysis revealed several unexpected trends."}'),
('20000000-0000-0000-0000-000000000371', 'typing', 14, '{"prompt_pt": "Traduza: ''A análise e a avaliação levaram à conclusão de que o processo precisa de uma descrição mais clara.''", "expected": "The analysis and the evaluation led to the conclusion that the process needs a clearer description.", "ai_review": true}'),

