('20000000-0000-0000-0000-000000000372', 'multiple_choice', 4, '{"question": "The ___ of the new product took over a year.", "audio_text": null, "options": ["development", "assessment", "variation"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000372', 'multiple_choice', 5, '{"question": "Meeting this ___ is essential for approval.", "audio_text": null, "options": ["requirement", "occurrence", "correlation"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000372', 'matching', 6, '{"pairs": [{"left": "development", "right": "desenvolvimento"}, {"left": "achievement", "right": "realização, conquista"}, {"left": "performance", "right": "desempenho"}, {"left": "improvement", "right": "melhoria"}, {"left": "involvement", "right": "envolvimento"}, {"left": "requirement", "right": "requisito"}]}'),
('20000000-0000-0000-0000-000000000372', 'fill_blank', 7, '{"sentence": "There has been a steady ___ in customer satisfaction.", "options": ["improvement", "limitation", "emergence"], "correct": "improvement", "translation": "Houve uma melhoria constante na satisfação do cliente."}'),
('20000000-0000-0000-0000-000000000372', 'fill_blank', 8, '{"sentence": "Her ___ in the project was crucial to its success.", "options": ["involvement", "distribution", "occurrence"], "correct": "involvement", "translation": "O envolvimento dela no projeto foi crucial para o sucesso."}'),
('20000000-0000-0000-0000-000000000372', 'word_order', 9, '{"words": ["Reducing", "costs", "by", "twenty", "percent", "was", "a", "major", "achievement"], "correct_sentence": "Reducing costs by twenty percent was a major achievement", "translation": "Reduzir os custos em vinte por cento foi uma grande conquista"}'),
('20000000-0000-0000-0000-000000000372', 'word_order', 10, '{"words": ["The", "team''s", "performance", "improved", "significantly", "this", "quarter"], "correct_sentence": "The team''s performance improved significantly this quarter", "translation": "O desempenho da equipe melhorou significativamente neste trimestre"}'),
('20000000-0000-0000-0000-000000000372', 'reading', 11, '{"passage": "Nominalization is also common with verbs describing progress and effort. ''Develop'' becomes ''development'', ''achieve'' becomes ''achievement'', ''perform'' becomes ''performance'', ''improve'' becomes ''improvement'', ''involve'' becomes ''involvement'', and ''require'' becomes ''requirement''. These noun forms make writing sound more formal and let the writer focus on the result rather than the action itself.", "translation": "A nominalização também é comum com verbos que descrevem progresso e esforço. ''Develop'' vira ''development'', ''achieve'' vira ''achievement'', ''perform'' vira ''performance'', ''improve'' vira ''improvement'', ''involve'' vira ''involvement'', e ''require'' vira ''requirement''. Essas formas em substantivo deixam a escrita mais formal e permitem que o autor foque no resultado, não na ação em si.", "question": "What do these noun forms let the writer focus on, according to the text?", "options": ["The result rather than the action itself", "The reader''s opinion", "The grammar rules"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000372', 'listening', 12, '{"audio_text": "The development of the new product took over a year. Reducing costs by twenty percent was a major achievement. Meeting this requirement is essential for approval.", "question": "How long did the development take, according to the audio?", "options": ["Over a year", "One month", "Two weeks"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000372', 'dictation', 13, '{"audio_text": "Meeting this requirement is essential for approval.", "expected": "Meeting this requirement is essential for approval."}'),
('20000000-0000-0000-0000-000000000372', 'typing', 14, '{"prompt_pt": "Traduza: ''O desenvolvimento do produto e o envolvimento da equipe levaram a uma grande melhoria no desempenho.''", "expected": "The development of the product and the involvement of the team led to a major improvement in performance.", "ai_review": true}'),

-- Lição 373: Substantivos de qualidade acadêmica (significance, effectiveness, accuracy, consistency, validity, complexity)
('20000000-0000-0000-0000-000000000373', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000002233", "show_image": false}'),
