('20000000-0000-0000-0000-000000000373', 'flashcard', 3, '{"vocabulary_id": "30000000-0000-0000-0000-000000002237", "show_image": false}'),
('20000000-0000-0000-0000-000000000373', 'multiple_choice', 4, '{"question": "The ___ of these findings cannot be overstated.", "audio_text": null, "options": ["significance", "occurrence", "distribution"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000373', 'multiple_choice', 5, '{"question": "Researchers questioned the ___ of the results.", "audio_text": null, "options": ["validity", "involvement", "emergence"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000373', 'matching', 6, '{"pairs": [{"left": "significance", "right": "importância, significância"}, {"left": "effectiveness", "right": "eficácia"}, {"left": "accuracy", "right": "precisão"}, {"left": "consistency", "right": "consistência"}, {"left": "validity", "right": "validade"}, {"left": "complexity", "right": "complexidade"}]}'),
('20000000-0000-0000-0000-000000000373', 'fill_blank', 7, '{"sentence": "The ___ of the forecast depends on reliable data.", "options": ["accuracy", "achievement", "variation"], "correct": "accuracy", "translation": "A precisão da previsão depende de dados confiáveis."}'),
('20000000-0000-0000-0000-000000000373', 'fill_blank', 8, '{"sentence": "The ___ of the system makes it hard to maintain.", "options": ["complexity", "requirement", "assumption"], "correct": "complexity", "translation": "A complexidade do sistema dificulta a manutenção."}'),
('20000000-0000-0000-0000-000000000373', 'word_order', 9, '{"words": ["The", "effectiveness", "of", "the", "new", "policy", "is", "still", "being", "measured"], "correct_sentence": "The effectiveness of the new policy is still being measured", "translation": "A eficácia da nova política ainda está sendo medida"}'),
('20000000-0000-0000-0000-000000000373', 'word_order', 10, '{"words": ["Consistency", "in", "the", "data", "collection", "process", "is", "essential"], "correct_sentence": "Consistency in the data collection process is essential", "translation": "A consistência no processo de coleta de dados é essencial"}'),
('20000000-0000-0000-0000-000000000373', 'reading', 11, '{"passage": "Adjectives can also become nouns through nominalization, especially in academic writing that evaluates quality. ''Significant'' becomes ''significance'', ''effective'' becomes ''effectiveness'', ''accurate'' becomes ''accuracy'', ''consistent'' becomes ''consistency'', ''valid'' becomes ''validity'', and ''complex'' becomes ''complexity''. These nouns often appear in sentences that discuss the strength or quality of research and results.", "translation": "Adjetivos também podem virar substantivos por meio da nominalização, especialmente em textos acadêmicos que avaliam qualidade. ''Significant'' vira ''significance'', ''effective'' vira ''effectiveness'', ''accurate'' vira ''accuracy'', ''consistent'' vira ''consistency'', ''valid'' vira ''validity'', e ''complex'' vira ''complexity''. Esses substantivos costumam aparecer em frases que discutem a força ou qualidade de pesquisas e resultados.", "question": "In what kind of sentences do these nouns often appear, according to the text?", "options": ["Sentences that discuss the strength or quality of research", "Casual conversations", "Instructions for a recipe"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000373', 'listening', 12, '{"audio_text": "The significance of these findings cannot be overstated. Researchers questioned the validity of the results. The complexity of the system makes it hard to maintain.", "question": "What did researchers question, according to the audio?", "options": ["The validity of the results", "The significance of the system", "The complexity of the findings"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000373', 'dictation', 13, '{"audio_text": "The significance of these findings cannot be overstated.", "expected": "The significance of these findings cannot be overstated."}'),
('20000000-0000-0000-0000-000000000373', 'typing', 14, '{"prompt_pt": "Traduza: ''A precisão e a consistência dos dados são essenciais para a validade da pesquisa.''", "expected": "The accuracy and consistency of the data are essential for the validity of the research.", "ai_review": true}'),

